-- 📚 꼭집 주거 사전 — 국민임대 순위 이원화 — 전용 50㎡ 미만 지역거주 / 이상 청약저축 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.6초 · 결과:
-- {"anns": 101, "by_std": {"국민임대": 101}, "50이원": 11, "50이원_ex": ["2015122300020899", "2015122300020779", "2015122300020754"], "거주지순위": 3, "거주지순위_ex": ["2015122300020754", "2015122300020663", "2015122300020328"], "납입순위": 6, "납입순위_ex": ["2015122300020779", "2015122300020734", "2015122300020696"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where std='국민임대'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where std='국민임대' group by 1)q),'50이원',(select count(distinct announcement_id) from y where std='국민임대' and t~'50\s*(㎡|m2|제곱미터)\s*(미만|이상)'),'50이원_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='국민임대' and t~'50\s*(㎡|m2|제곱미터)\s*(미만|이상)' order by 1 desc limit 3)q),'거주지순위',(select count(distinct announcement_id) from y where std='국민임대' and t~'50\s*(㎡|m2)\s*미만[^■]{0,120}(거주|지역)'),'거주지순위_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='국민임대' and t~'50\s*(㎡|m2)\s*미만[^■]{0,120}(거주|지역)' order by 1 desc limit 3)q),'납입순위',(select count(distinct announcement_id) from y where std='국민임대' and t~'50\s*(㎡|m2)\s*이상[^■]{0,120}(납입|청약)'),'납입순위_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='국민임대' and t~'50\s*(㎡|m2)\s*이상[^■]{0,120}(납입|청약)' order by 1 desc limit 3)q))j;
